#define main historical_native_main
#include "native_corrected/main.cu"
#undef main
#include <vector>
#include <string>
#include <fstream>
#include <algorithm>
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct P{int nx,ny,ns,ndx,ndy,np;double dx,dy,dz,du,dv,DSD,DDR,DAG;};
std::vector<double>load(const char*name,size_t n){std::vector<double>x(n);std::ifstream f(std::string("/home/imo/HeCBench_julia/src/ddbp-julia/")+name,std::ios::binary);f.read((char*)x.data(),n*8);if(!f){fprintf(stderr,"fixture\n");exit(2);}return x;}
struct Buffers{std::vector<double*>base,a;std::vector<size_t>n;Buffers(P p){int X=p.ndx+1,Y=p.ndy+1,OX=p.nx+1,OY=p.ny+1;n={size_t(X*Y*p.np),size_t(OX*OY),size_t(p.nx*p.ny*p.ns),size_t(X),size_t(Y),size_t(Y),size_t(OX),size_t(OY),size_t(p.ns),size_t(Y),size_t(X*Y),size_t(Y),size_t(Y)};for(auto sz:n){double*b;CHECK(cudaMalloc(&b,(sz+32)*8));std::vector<double>h(sz+32,-8192);CHECK(cudaMemcpy(b,h.data(),h.size()*8,cudaMemcpyHostToDevice));base.push_back(b);a.push_back(b+16);}}~Buffers(){for(auto b:base)cudaFree(b);}};
void pipeline(Buffers&B,P p,const std::vector<double>&data,const std::vector<double>&ta,const std::vector<double>&da,bool capture,std::vector<double>&prefix,std::vector<double>&states){auto&A=B.a;int X=p.ndx+1,Y=p.ndy+1,OX=p.nx+1,OY=p.ny+1;auto cap=[&](bool input,std::initializer_list<int>ids){if(!capture)return;CHECK(cudaDeviceSynchronize());for(auto i:ids){std::vector<double>x(B.n[i]);CHECK(cudaMemcpy(x.data(),A[i],x.size()*8,cudaMemcpyDeviceToHost));auto&dest=input?prefix:states;dest.insert(dest.end(),x.begin(),x.end());}};
for(int np=0;np<p.np;np++){pad_projections_kernel<<<X/256+1,256>>>(A[0],X,Y,X,np);CHECK(cudaMemset(A[0]+np*X*Y+1,0,p.ny*8));}for(int np=0;np<p.np;np++)for(int c=0;c<p.ndx;c++)CHECK(cudaMemcpy(A[0]+np*X*Y+(c+1)*Y+1,data.data()+np*p.ndx*p.ndy+c*p.ndy,p.ndy*8,cudaMemcpyHostToDevice));cap(true,{0});
map_boudaries_kernel<<<p.ndx/256+1,256>>>(A[3],X,p.ndx,-p.du,0);map_boudaries_kernel<<<p.ndy/256+1,256>>>(A[4],Y,p.ndy/2.,p.dv,0);map_boudaries_kernel<<<p.nx/256+1,256>>>(A[6],OX,p.nx,-p.dx,0);map_boudaries_kernel<<<p.ny/256+1,256>>>(A[7],OY,p.ny/2.,p.dy,0);map_boudaries_kernel<<<p.ns/256+1,256>>>(A[8],p.ns,0,p.dz,p.DAG+p.dz/2);CHECK(cudaMemset(A[5],0,Y*8));CHECK(cudaMemset(A[2],0,p.nx*p.ny*p.ns*8));cap(false,{3,4,5,6,7,8});
img_integration_kernel<<<(Y*p.np+255)/256,256>>>(A[0],X,Y,integrateXcoord,0,0,p.np);cap(false,{0});img_integration_kernel<<<(X*p.np+255)/256,256>>>(A[0],X,Y,integrateYcoord,0,0,p.np);cap(false,{0});
for(int np=0;np<p.np;np++){double theta=ta[np]*M_PI/180.,phi=da[np]*M_PI/180.;double ty=-(p.DSD-p.DDR)*sin(theta),tz=(p.DSD-p.DDR)*cos(theta)+p.DDR;rot_detector_kernel<<<Y/256+1,256>>>(A[11],A[12],A[4],A[5],0,p.DDR,phi,Y);cap(false,{11,12});for(int nz=0;nz<p.ns;nz++){mapDet2Slice_kernel<<<dim3(Y/16+1,X/16+1,1),dim3(16,16,1)>>>(A[10],A[9],0,ty,tz,A[3],A[11],A[12],A[8],X,Y,nz);cap(false,{10,9});bilinear_interpolation_kernel<<<dim3(OY/16+1,OX/16+1,1),dim3(16,16,1)>>>(A[1],A[0],A[6],A[7],A[10]+Y*(X-2),A[9],OX,OY,X,Y,p.ndx,p.ndy,np);cap(false,{1});differentiation_kernel<<<dim3(p.ny/16+1,p.nx/16+1,1),dim3(16,16,1)>>>(A[2],A[1],0,ty,tz,A[6],A[7],A[8],p.nx,p.ny,OX,OY,p.du,p.dv,p.dx,p.dy,p.dz,nz);cap(false,{2});}}
division_kernel<<<dim3(p.ny/8+1,p.nx/8+1,p.ns/4+1),dim3(8,8,4)>>>(A[2],p.nx,p.ny,p.ns,p.np);cap(false,{2});CHECK(cudaGetLastError());}
int main(){P params[2]={{8,8,1,8,8,1,1,1,1,1,1,8,0,-.5},{7,8,2,8,8,3,.9,1,.5,1,1,20,2,1}};std::vector<double>ta[2]={{0},{-5,0,4}},da[2]={{0},{-2,.5,1.5}},data[2]={load("study_proj1_f64.bin",64),load("study_proj2_f64.bin",192)},oracle[2]={load("oracle_case1_f64.bin",525),load("oracle_case2_f64.bin",2342)};Buffers a(params[0]),b(params[1]);Buffers*buf[2]={&a,&b};std::vector<double>dummy;for(int ci=0;ci<2;ci++)pipeline(*buf[ci],params[ci],data[ci],ta[ci],da[ci],false,dummy,dummy);CHECK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){std::vector<double>prefix,states,guards;double times[2],err=0,rel=0;bool ok=true;for(int ci=0;ci<2;ci++){P p=params[ci];CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int j=0;j<3;j++)pipeline(*buf[ci],p,data[ci],ta[ci],da[ci],false,dummy,dummy);CHECK(cudaDeviceSynchronize());times[ci]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;std::vector<double>lp,ls;pipeline(*buf[ci],p,data[ci],ta[ci],da[ci],true,lp,ls);CHECK(cudaDeviceSynchronize());lp.insert(lp.end(),ta[ci].begin(),ta[ci].end());lp.insert(lp.end(),da[ci].begin(),da[ci].end());lp.insert(lp.end(),{double(p.nx),double(p.ny),double(p.ns),double(p.ndx),double(p.ndy),double(p.np),p.dx,p.dy,p.dz,p.du,p.dv,p.DSD,p.DDR,p.DAG});prefix.insert(prefix.end(),lp.begin(),lp.end());states.insert(states.end(),ls.begin(),ls.end());if(ls.size()!=oracle[ci].size())return 3;for(size_t i=0;i<ls.size();i++){double e=std::abs(ls[i]-oracle[ci][i]);err=std::max(err,e);rel=std::max(rel,e/std::max(std::abs(oracle[ci][i]),2.220446049250313e-16));ok&=std::isfinite(ls[i])&&e<=1e-10+1e-9*std::abs(oracle[ci][i]);}for(size_t i=0;i<buf[ci]->n.size();i++){std::vector<double>raw(buf[ci]->n[i]+32);CHECK(cudaMemcpy(raw.data(),buf[ci]->base[i],raw.size()*8,cudaMemcpyDeviceToHost));for(size_t j=0;j<16;j++){guards.push_back(raw[j]);ok&=raw[j]==-8192;}for(size_t j=raw.size()-16;j<raw.size();j++){guards.push_back(raw[j]);ok&=raw[j]==-8192;}}}all&=ok;auto artifact=prefix;artifact.insert(artifact.end(),states.begin(),states.end());artifact.insert(artifact.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)artifact.data(),artifact.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":3699,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"sum_two_corrected_backprojection_original_preallocated_padding_H2D_maps_scans_geometry_interpolation_differentiation_normalization_regions\",\"jit_excluded\":true,\"internal_repeats\":3,\"timed_cases\":2,\"component_time_seconds\":{\"analytic_plane\":%.12g,\"varied_views\":%.12g},\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1],ok?"true":"false",err,rel,times[0],times[1],path.c_str(),artifact.size());}return all?0:1;}
